// Lightweight local onset / autocorrelation beat estimate. No audio uploads.
export function onsetEnvelope(left,right,rate){const hop=Math.max(1,Math.round(rate/100)),n=Math.ceil(left.length/hop),energy=new Float32Array(n),flux=new Float32Array(n);let slow=0;for(let f=0;f<n;f++){let sum=0,count=0;for(let i=f*hop;i<Math.min(left.length,(f+1)*hop);i+=2){const l=left[i],r=right?.[i]??l;sum+=(l*l+r*r)*.5;count++}energy[f]=Math.sqrt(sum/Math.max(1,count));slow=.85*slow+.15*energy[f];flux[f]=Math.max(0,energy[f]-slow)}return {envelope:flux,rate:rate/hop,duration:left.length/rate}}
export function detectBeats(envelope,rate,duration){if(duration<6)throw Error('Use pelo menos 6 segundos de áudio para estimar o beat.');let peak=0,power=0;for(const x of envelope){peak=Math.max(peak,x);power+=x*x}if(peak<1e-5||power<1e-8)throw Error('Não foi encontrado pulso suficiente. Informe o BPM manualmente.');const x=Float32Array.from(envelope,v=>v/peak),minLag=Math.ceil(rate*60/180),maxLag=Math.floor(rate*60/60);const correlation=lag=>{let sum=0,a=0,b=0;for(let i=lag;i<x.length;i++){sum+=x[i]*x[i-lag];a+=x[i]*x[i];b+=x[i-lag]*x[i-lag]}return sum/Math.sqrt(a*b||1)};let bestLag=0,best=-Infinity;const scores=[];for(let lag=minLag;lag<=maxLag;lag++){const corr=correlation(lag);const score=corr+.25*correlation(lag*2);scores.push({lag,corr,score});if(score>best){best=score;bestLag=lag}}
const corr=scores.find(s=>s.lag===bestLag).corr;if(corr<.12)throw Error('Pulso irregular ou pouco definido. Use BPM e alinhamento manuais.');
// Refine fractional lag using neighbouring autocorrelation values.
const prev=correlation(bestLag-1),next=correlation(bestLag+1),den=prev-2*corr+next;const lag=bestLag+(Math.abs(den)>1e-8?Math.max(-.5,Math.min(.5,.5*(prev-next)/den)):0),period=lag/rate;
let phase=0,phaseScore=-1;for(let p=0;p<Math.ceil(lag);p++){let sum=0;for(let f=p;f<x.length;f+=lag){const j=Math.round(f);sum+=Math.max(x[j]||0,(x[j-1]||0)*.8,(x[j+1]||0)*.8)}if(sum>phaseScore){phaseScore=sum;phase=p}}
// Follow local onset peaks while limiting drift; maintain grid through quiet gaps.
const beats=[],radius=Math.max(1,Math.round(lag*.13));let prediction=phase;while(prediction<x.length){const center=Math.round(prediction);let found=center,value=0;for(let i=Math.max(0,center-radius);i<=Math.min(x.length-1,center+radius);i++){const score=x[i]*(1-.35*Math.abs(i-center)/radius);if(score>value){value=score;found=i}}const at=value>.035?found:prediction;const time=at/rate;if(time>=0&&time<duration&&(!beats.length||time-beats.at(-1)>period*.5))beats.push(time);prediction+=lag;if(value>.035)prediction+=(found-center)*.12}
return {bpm:60/period,offset:beats[0]||0,beats,confidence:Math.max(0,Math.min(1,corr)),method:'onset-autocorrelation'};}
